import { FiMapPin, FiMail, FiPhone, FiBriefcase, FiCopy } from 'react-icons/fi';
import { useState, useEffect } from 'react';
import { toast } from 'react-hot-toast';

const ContactDetailsCards = () => {
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const handleAction = (type, value) => {
    if (!isMounted) return;

    switch (type) {
      case 'email':
        navigator.clipboard.writeText(value);
        toast.success('Email copied to clipboard!', {
          icon: '📧',
          position: 'bottom-center'
        });
        window.location.href = `mailto:${value}`;
        break;
      case 'phone':
        navigator.clipboard.writeText(value);
        toast.success('Phone number copied!', {
          icon: '📱',
          position: 'bottom-center'
        });
        window.location.href = `tel:${value.replace(/-/g, '')}`;
        break;
      default:
        navigator.clipboard.writeText(value);
        toast.success('Copied to clipboard!', {
          position: 'bottom-center'
        });
    }
  };

  const contactItems = [
    { 
      icon: <FiMapPin className="w-5 h-5" />,
      label: "Location",
      detail: "Islamabad, Pakistan",
      color: "text-blue-500",
      bgColor: "bg-blue-50 dark:bg-blue-900/20",
      hoverColor: "hover:bg-blue-100 dark:hover:bg-blue-900/30",
      action: false
    },
    { 
      icon: <FiMail className="w-5 h-5" />,
      label: "Email",
      detail: "mrhahzaibabbasi@gmail.com",
      color: "text-red-500",
      bgColor: "bg-red-50 dark:bg-red-900/20",
      hoverColor: "hover:bg-red-100 dark:hover:bg-red-900/30",
      action: 'email'
    },
    { 
      icon: <FiPhone className="w-5 h-5" />,
      label: "Phone",
      detail: "0316-7835469",
      color: "text-green-500",
      bgColor: "bg-green-50 dark:bg-green-900/20",
      hoverColor: "hover:bg-green-100 dark:hover:bg-green-900/30",
      action: 'phone'
    },
    { 
      icon: <FiBriefcase className="w-5 h-5" />,
      label: "Availability",
      detail: "Open to Freelance / Full-time",
      color: "text-purple-500",
      bgColor: "bg-purple-50 dark:bg-purple-900/20",
      hoverColor: "hover:bg-purple-100 dark:hover:bg-purple-900/30",
      action: false
    }
  ];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 md:py-16 lg:py-20">
      <div className="text-center mb-12 lg:mb-16">
        <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold text-gray-800 dark:text-white mb-4">
          Get In <span className="bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">Touch</span>
        </h2>
        <p className="mt-3 text-lg md:text-xl text-gray-600 dark:text-gray-300 max-w-3xl mx-auto">
          Feel free to reach out for collaborations or just a friendly hello
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 lg:gap-8">
        {contactItems.map((item, index) => (
          <div 
            key={index}
            onClick={() => item.action && handleAction(item.action, item.detail)}
            className={`relative overflow-hidden rounded-2xl p-6 lg:p-8 ${item.bgColor} ${item.hoverColor} transition-all duration-300 group border border-gray-100 dark:border-gray-700/50 shadow-sm hover:shadow-lg cursor-default ${item.action ? 'cursor-pointer' : ''}`}
          >
            {/* Icon with animated background */}
            <div className={`w-14 h-14 rounded-xl ${item.color} bg-white dark:bg-gray-800 flex items-center justify-center mb-5 shadow-inner group-hover:scale-110 transition-transform duration-300`}>
              {item.icon}
            </div>
            
            {/* Content */}
            <h3 className="text-lg lg:text-xl font-semibold text-gray-800 dark:text-white mb-2">{item.label}</h3>
            <div className="flex items-center justify-between">
              <p className="text-gray-600 dark:text-gray-300 text-base lg:text-lg pr-2">
                {item.detail}
              </p>
              {item.action && (
                <button 
                  className={`p-2 rounded-full ${item.color} hover:bg-white dark:hover:bg-gray-800 transition-colors`}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleAction(item.action, item.detail);
                  }}
                  aria-label={`Copy ${item.label}`}
                >
                  <FiCopy className="w-4 h-4" />
                </button>
              )}
            </div>
            
            {/* Animated border bottom */}
            <div className={`absolute bottom-0 left-0 h-1 w-0 ${item.color.replace('text', 'bg')} transition-all duration-500 group-hover:w-full`}></div>
            
            {/* Subtle hover effect */}
            <div className={`absolute inset-0 opacity-0 group-hover:opacity-10 ${item.color.replace('text', 'bg')} transition-opacity duration-300`}></div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ContactDetailsCards;